void setup() {
  pinMode(2, INPUT);   // Brytar som input
  pinMode(13, OUTPUT); // LED som output
}

void loop() {
  if (digitalRead(2) == HIGH) {
    digitalWrite(13, HIGH);  // LED på
  } else {
    digitalWrite(13, LOW);   // LED av
  }
}

